def qualifying_child(relationship_152_c_2: bool, same_abode_days: int, tax_year_days: int, younger_than_taxpayer: bool, age_at_year_end: int, joint_nonrefund_return: bool) -> bool:
    if not relationship_152_c_2:
        return False
    if same_abode_days <= tax_year_days // 2:
        return False
    if not younger_than_taxpayer:
        return False
    if age_at_year_end >= 25:
        return False
    if joint_nonrefund_return:
        return False
    return True
